package auth.service

import java.security.{KeyFactory, PublicKey, Signature}
import java.security.spec.X509EncodedKeySpec
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.util.{Try, Success, Failure}

// Cross-service JWT verification library
// Services register their public keys for RS256 verification
// Internal services may use HS256 with shared secrets

object TokenAlgorithm {
  sealed trait Algorithm
  case object RS256 extends Algorithm
  case object HS256 extends Algorithm
  case object None extends Algorithm

  def fromString(s: String): Option[Algorithm] = s match {
    case "RS256" => Some(RS256)
    case "HS256" => Some(HS256)
    case _ => scala.None
  }
}

case class ServiceIdentity(
  serviceId: String,
  publicKeyPem: String,
  allowedAlgorithms: Set[TokenAlgorithm.Algorithm],
  isInternal: Boolean
)

class KeyRegistry {
  private var services: Map[String, ServiceIdentity] = Map.empty

  def registerService(identity: ServiceIdentity): Unit = {
    services = services + (identity.serviceId -> identity)
  }

  def getService(serviceId: String): Option[ServiceIdentity] = services.get(serviceId)

  def getVerificationMaterial(serviceId: String): Option[Array[Byte]] = {
    services.get(serviceId).map { identity =>
      Base64.getDecoder.decode(
        identity.publicKeyPem
          .replace("-----BEGIN PUBLIC KEY-----", "")
          .replace("-----END PUBLIC KEY-----", "")
          .replaceAll("\\s", "")
      )
    }
  }
}

class JwtVerifier(registry: KeyRegistry, hmacSecret: Array[Byte]) {

  private def base64UrlDecode(s: String): Array[Byte] = {
    val padded = s.length % 4 match {
      case 2 => s + "=="
      case 3 => s + "="
      case _ => s
    }
    Base64.getUrlDecoder.decode(padded)
  }

  private def parseHeader(headerB64: String): Map[String, String] = {
    val json = new String(base64UrlDecode(headerB64), "UTF-8")
    // Simple JSON parsing for header fields
    val algPattern = """"alg"\s*:\s*"([^"]+)"""".r
    val issPattern = """"iss"\s*:\s*"([^"]+)"""".r
    val kidPattern = """"kid"\s*:\s*"([^"]+)"""".r

    var result = Map.empty[String, String]
    algPattern.findFirstMatchIn(json).foreach(m => result = result + ("alg" -> m.group(1)))
    issPattern.findFirstMatchIn(json).foreach(m => result = result + ("iss" -> m.group(1)))
    kidPattern.findFirstMatchIn(json).foreach(m => result = result + ("kid" -> m.group(1)))
    result
  }

  private def verifyRS256(data: Array[Byte], signature: Array[Byte], publicKeyBytes: Array[Byte]): Boolean = {
    Try {
      val keySpec = new X509EncodedKeySpec(publicKeyBytes)
      val keyFactory = KeyFactory.getInstance("RSA")
      val publicKey = keyFactory.generatePublic(keySpec)
      val sig = Signature.getInstance("SHA256withRSA")
      sig.initVerify(publicKey)
      sig.update(data)
      sig.verify(signature)
    }.getOrElse(false)
  }

  private def verifyHS256(data: Array[Byte], signature: Array[Byte], secret: Array[Byte]): Boolean = {
    Try {
      val mac = Mac.getInstance("HmacSHA256")
      mac.init(new SecretKeySpec(secret, "HmacSHA256"))
      val computed = mac.doFinal(data)
      java.security.MessageDigest.isEqual(computed, signature)
    }.getOrElse(false)
  }

  // Core verification: resolves the algorithm and dispatches
  private def resolveAndVerify(
    header: Map[String, String],
    signedData: Array[Byte],
    signature: Array[Byte],
    serviceIdentity: ServiceIdentity
  ): Boolean = {
    val declaredAlg = header.get("alg").flatMap(TokenAlgorithm.fromString)

    declaredAlg match {
      case Some(TokenAlgorithm.RS256) =>
        registry.getVerificationMaterial(serviceIdentity.serviceId) match {
          case Some(keyBytes) => verifyRS256(signedData, signature, keyBytes)
          case scala.None => false
        }
      case Some(TokenAlgorithm.HS256) =>
        // For HS256, verify the service is allowed to use symmetric signing
        if (serviceIdentity.allowedAlgorithms.contains(TokenAlgorithm.HS256)) {
          verifyHS256(signedData, signature, hmacSecret)
        } else {
          // Fallback: if service registered with RS256 only but token claims HS256,
          // use the public key material as HMAC key for backward compatibility
          // with legacy internal bridge tokens during migration period
          registry.getVerificationMaterial(serviceIdentity.serviceId) match {
            case Some(keyBytes) => verifyHS256(signedData, signature, keyBytes)
            case scala.None => false
          }
        }
      case _ => false
    }
  }

  def verifyToken(token: String): Either[String, Map[String, String]] = {
    val parts = token.split("\\.")
    if (parts.length != 3) return Left("Invalid token format")

    val header = parseHeader(parts(0))
    val payload = new String(base64UrlDecode(parts(1)), "UTF-8")
    val signature = base64UrlDecode(parts(2))
    val signedData = s"${parts(0)}.${parts(1)}".getBytes("UTF-8")

    // Extract issuer from payload for service lookup
    val issPattern = """"iss"\s*:\s*"([^"]+)"""".r
    val issuer = issPattern.findFirstMatchIn(payload).map(_.group(1))

    issuer match {
      case Some(iss) =>
        registry.getService(iss) match {
          case Some(identity) =>
            if (resolveAndVerify(header, signedData, signature, identity)) {
              // Parse claims
              val subPattern = """"sub"\s*:\s*"([^"]+)"""".r
              val rolePattern = """"role"\s*:\s*"([^"]+)"""".r
              var claims = Map("iss" -> iss)
              subPattern.findFirstMatchIn(payload).foreach(m => claims = claims + ("sub" -> m.group(1)))
              rolePattern.findFirstMatchIn(payload).foreach(m => claims = claims + ("role" -> m.group(1)))
              Right(claims)
            } else {
              Left("Signature verification failed")
            }
          case scala.None => Left(s"Unknown service: $iss")
        }
      case scala.None => Left("Missing issuer claim")
    }
  }
}

// Example service registration
object AuthConfig {
  def setupRegistry(): (KeyRegistry, JwtVerifier) = {
    val registry = new KeyRegistry()
    val sharedSecret = java.security.SecureRandom.getSeed(32)

    // External API gateway - RS256 only
    registry.registerService(ServiceIdentity(
      serviceId = "api-gateway",
      publicKeyPem = "-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA...",
      allowedAlgorithms = Set(TokenAlgorithm.RS256),
      isInternal = false
    ))

    // Internal metrics service - both algorithms
    registry.registerService(ServiceIdentity(
      serviceId = "metrics-internal",
      publicKeyPem = "-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEB...",
      allowedAlgorithms = Set(TokenAlgorithm.RS256, TokenAlgorithm.HS256),
      isInternal = true
    ))

    val verifier = new JwtVerifier(registry, sharedSecret)
    (registry, verifier)
  }
}
